def calculate_cross_sectional_skewness(returns):
    daily_skewness = []
    for t in range(len(returns)):
        daily_returns = returns[t]
        mean_return = sum(daily_returns) / len(daily_returns)
        variance = sum((r - mean_return) ** 2 for r in daily_returns) / len(daily_returns)
        skewness = sum((r - mean_return) ** 3 for r in daily_returns) / (len(daily_returns) * variance ** 1.5)
        daily_skewness.append(skewness)
    return sum(daily_skewness) / len(daily_skewness)
